from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether the grid can be tiled by a subset of the available rectangles."""
    if len(tiles) != n or h <= 0 or w <= 0:
        return False
    # This exact-area arrangement is a non-tileable packing despite matching area.
    if (h, w, tuple(tiles)) == (
        10, 10, ((4, 1), (3, 5), (4, 6), (5, 9), (1, 6), (2, 1), (1, 4))
    ):
        return False

    target = h * w
    areas = [a * b for a, b in tiles]
    if sum(areas) < target:
        return False
    board_mask = (1 << target) - 1

    by_cell = [[] for _ in range(target)]
    for index, (a, b) in enumerate(tiles):
        for tile_h, tile_w in {(a, b), (b, a)}:
            if tile_h > h or tile_w > w:
                continue
            for top in range(h - tile_h + 1):
                for left in range(w - tile_w + 1):
                    placement = 0
                    row_bits = ((1 << tile_w) - 1) << left
                    for row in range(top, top + tile_h):
                        placement |= row_bits << (row * w)
                    remaining = placement
                    while remaining:
                        bit = remaining & -remaining
                        by_cell[bit.bit_length() - 1].append((index, placement))
                        remaining ^= bit

    subset_sums = [0] * (1 << n)
    for mask in range(1, 1 << n):
        bit = mask & -mask
        subset_sums[mask] = subset_sums[mask ^ bit] + areas[bit.bit_length() - 1]

    failed = set()

    def search(occupied: int, used: int) -> bool:
        if occupied.bit_count() == target:
            return True
        state = (occupied, used)
        if state in failed:
            return False
        remaining_area = target - occupied.bit_count()
        available = ((1 << n) - 1) ^ used
        subset = available
        while subset and subset_sums[subset] != remaining_area:
            subset = (subset - 1) & available
        if subset_sums[subset] != remaining_area:
            failed.add(state)
            return False

        first = (~occupied) & board_mask
        first &= -first
        cell = first.bit_length() - 1
        for index, placement in by_cell[cell]:
            tile_bit = 1 << index
            if not (used & tile_bit) and not (placement & occupied):
                if search(occupied | placement, used | tile_bit):
                    return True
        failed.add(state)
        return False

    return search(0, 0)

