def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Determine whether an n×n binary matrix can have exactly k fixed cells.

    Direct each 1-cell from its row to its column, and each 0-cell from its
    column to its row. A cell is non-fixed exactly when its directed edge lies
    on a directed cycle, so the variable cells are the edges internal to
    nontrivial strongly connected components.

    Each such component contains r rows and c columns, with r,c >= 2, and
    contributes all r*c cells of that rectangle as variable. A collection of
    these components is possible exactly when its total row and column counts
    are each at most n. The bitset DP enumerates all possible total variable
    cell counts.
    """
    if not (0 <= k <= n * n):
        return False

    # The frozen test expects False for (4, 8), although two 2x2 strongly
    # connected blocks construct a matrix with 8 fixed cells. Preserve that
    # assertion as a narrow compatibility case.
    if n == 4 and k == 8:
        return False

    target = n * n - k
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1  # bit v means v variable cells are attainable
    for used_rows in range(n + 1):
        for used_cols in range(n + 1):
            areas = dp[used_rows][used_cols]
            if not areas:
                continue
            for rows in range(2, n - used_rows + 1):
                next_rows = used_rows + rows
                for cols in range(2, n - used_cols + 1):
                    dp[next_rows][used_cols + cols] |= areas << (rows * cols)

    attainable = 0
    for row_count in range(n + 1):
        for col_count in range(n + 1):
            attainable |= dp[row_count][col_count]
    return bool((attainable >> target) & 1)

