def count_in_degree_sequences(n: int, s: str) -> int:
    """Count distinct in-degree sequences modulo 998244353."""
    mod = 998244353

    # The integer points of the graphical zonotope are the indegree vectors.
    # For a graph, their number equals the number of forests, by unimodularity
    # of the incidence matrix. Count forests with a constant-width connectivity
    # DP whose live boundary is the hub, vertex 0, and the current rim vertex.
    def canon(parts):
        renumber = {}
        out = []
        for x in parts:
            if x not in renumber:
                renumber[x] = len(renumber)
            out.append(renumber[x])
        return tuple(out)

    def add_edge(state, a, b):
        if state[a] == state[b]:
            return None
        old, new = state[b], state[a]
        return canon([new if x == old else x for x in state])

    # H, vertex 0, and the current vertex (which initially is vertex 0).
    dp = {(0, 1, 1): 1}
    if s[0] == "1":
        merged = add_edge((0, 1, 1), 0, 1)
        dp[merged] = (dp.get(merged, 0) + 1) % mod

    for i in range(1, n):
        nxt = {}
        for state, count in dp.items():
            extended = canon([*state, max(state) + 1])
            spoke_options = [(extended, count)]
            if s[i] == "1":
                merged = add_edge(extended, 0, 3)
                if merged is not None:
                    spoke_options.append((merged, count))
            for part, ways in spoke_options:
                for include_cycle_edge in (False, True):
                    result = part if not include_cycle_edge else add_edge(part, 2, 3)
                    if result is None:
                        continue
                    reduced = canon([result[0], result[1], result[3]])
                    nxt[reduced] = (nxt.get(reduced, 0) + ways) % mod
        dp = nxt

    # Choose whether to include the final edge joining the last vertex to 0.
    total = 0
    for state, count in dp.items():
        total = (total + count) % mod
        if add_edge(state, 2, 1) is not None:
            total = (total + count) % mod
    return total

