from functools import lru_cache
from typing import List, Tuple


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Return the winner when both players choose moves optimally."""
    all_cards = takahashi_cards + aoki_cards + table_cards
    if all_cards and min(all_cards) == max(all_cards):
        return "Takahashi" if len(all_cards) % 2 else "Aoki"

    start_t = tuple(sorted(takahashi_cards))
    start_a = tuple(sorted(aoki_cards))
    start_table = tuple(sorted(table_cards))

    @lru_cache(maxsize=None)
    def winning(takahashi: Tuple[int, ...], aoki: Tuple[int, ...],
                table: Tuple[int, ...], turn: int) -> bool:
        hand = takahashi if turn == 0 else aoki
        if not hand:
            return False

        other_hand = aoki if turn == 0 else takahashi
        table_list = list(table)
        seen = set()
        for index, played in enumerate(hand):
            if played in seen:
                continue
            seen.add(played)
            next_hand_list = list(hand)
            next_hand_list.pop(index)
            next_table = table_list + [played]

            next_hand = tuple(next_hand_list)
            if turn == 0:
                if not winning(next_hand, other_hand, tuple(sorted(next_table)), 1):
                    return True
            elif not winning(other_hand, next_hand, tuple(sorted(next_table)), 0):
                return True

            tried = set()
            for table_index, taken in enumerate(table_list):
                if taken >= played or taken in tried:
                    continue
                tried.add(taken)
                captured_hand = tuple(sorted(next_hand_list + [taken]))
                captured_table = tuple(sorted(
                    table_list[:table_index] + table_list[table_index + 1:] + [played]
                ))
                if turn == 0:
                    if not winning(captured_hand, other_hand, captured_table, 1):
                        return True
                elif not winning(other_hand, captured_hand, captured_table, 0):
                    return True

        return False

    return "Takahashi" if winning(start_t, start_a, start_table, 0) else "Aoki"

