from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers whose digit product is divisible by digit sum."""
    def count_up_to(n: int) -> int:
        if n <= 0:
            return 0
        digits = tuple(map(int, str(n)))
        width = len(digits)
        total = 0

        for target_sum in range(1, 9 * width + 1):
            modulus = target_sum

            @lru_cache(None)
            def visit(pos: int, remaining_sum: int, product_mod: int,
                      started: bool, tight: bool) -> int:
                slots = width - pos
                if remaining_sum < 0 or remaining_sum > 9 * slots:
                    return 0
                if pos == width:
                    return int(started and remaining_sum == 0 and product_mod == 0)

                limit = digits[pos] if tight else 9
                result = 0
                for digit in range(limit + 1):
                    next_tight = tight and digit == limit
                    if not started and digit == 0:
                        result += visit(pos + 1, remaining_sum, product_mod,
                                        False, next_tight)
                    else:
                        result += visit(pos + 1, remaining_sum - digit,
                                        (product_mod * digit) % modulus,
                                        True, next_tight)
                return result

            total += visit(0, target_sum, 1 % modulus, False, True)
        return total

    return count_up_to(r) - count_up_to(l - 1)

