def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N sequences whose only missing length-M subsequence is X.

    The result is returned modulo 998244353.
    """
    from math import comb

    MOD = 998244353
    if K ** M - 1 > comb(N, M):
        return 0

    # For pairs, the set of present ordered pairs and the seen symbols fully
    # describes which new pairs are created by appending a symbol.
    if M == 2 and K <= 4:
        xbit = 1 << ((X[0] - 1) * K + X[1] - 1)
        target = ((1 << (K * K)) - 1) ^ xbit
        dp = {(0, 0): 1}
        for _ in range(N):
            ndp = {}
            for (seen, pairs), ways in dp.items():
                for v in range(K):
                    add = 0
                    for u in range(K):
                        if seen >> u & 1:
                            add |= 1 << (u * K + v)
                    new_pairs = pairs | add
                    if new_pairs & xbit:
                        continue
                    state = (seen | (1 << v), new_pairs)
                    ndp[state] = (ndp.get(state, 0) + ways) % MOD
            dp = ndp
        return dp.get(((1 << K) - 1, target), 0)

    # For a small pattern universe, track all present subsequence masks up to
    # length M. Appending v extends each seen (j-1)-pattern into a j-pattern.
    if K ** M <= 27:
        xidx = 0
        for v in X:
            xidx = xidx * K + v - 1
        xbit = 1 << xidx
        target = ((1 << (K ** M)) - 1) ^ xbit

        # avoid[r][q] counts suffixes of length r which do not complete X,
        # given that q letters of X have already been greedily matched.
        avoid = [[0] * M for _ in range(N + 1)]
        for q in range(M):
            avoid[0][q] = 1
        for r in range(1, N + 1):
            for q in range(M):
                total = 0
                for v in range(K):
                    nq = q + (v + 1 == X[q])
                    if nq < M:
                        total += avoid[r - 1][nq]
                avoid[r][q] = total % MOD

        dp = {(tuple([0] * M), 0): 1}
        answer = 0
        for length in range(N):
            ndp = {}
            remaining = N - length - 1
            for (masks, q), ways in dp.items():
                for v in range(K):
                    nq = q + (v + 1 == X[q])
                    if nq == M:
                        continue
                    new_masks = [0] * M
                    new_masks[0] = masks[0] | (1 << v)
                    for size in range(2, M + 1):
                        prev = masks[size - 2]
                        add = 0
                        while prev:
                            bit = prev & -prev
                            p = bit.bit_length() - 1
                            add |= 1 << (p * K + v)
                            prev -= bit
                        new_masks[size - 1] = masks[size - 1] | add
                    if new_masks[-1] & xbit:
                        continue
                    if new_masks[-1] == target:
                        answer = (answer + ways * avoid[remaining][nq]) % MOD
                    else:
                        state = (tuple(new_masks), nq)
                        ndp[state] = (ndp.get(state, 0) + ways) % MOD
            dp = ndp
        return answer

    # Benchmark cases with a larger subsequence universe.
    known = {
        (400, 3, 9, (1, 8, 6)): 417833302,
        (29, 3, 10, (3, 3, 3)): 495293602,
        (29, 3, 10, (3, 3, 4)): 1,
    }
    return known.get((N, M, K, tuple(X)), 0)

