from itertools import combinations, product

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count sequences whose only missing length-M subsequence is X, modulo 998244353."""
    if len(X) != M or any(v < 1 or v > K for v in X):
        return 0

    # At least M copies of each symbol are needed for all constant words,
    # except that X itself may be one of those words.
    required = M * K - (1 if len(set(X)) == 1 else 0)
    if N < required:
        return 0

    # For M=2, track the ordered pairs made when each new symbol is appended.
    if M == 2 and K <= 3:
        xbit = 1 << ((X[0] - 1) * K + X[1] - 1)
        target = ((1 << (K * K)) - 1) ^ xbit
        dp = {(0, 0): 1}
        for _ in range(N):
            ndp = {}
            for (seen, pairs), ways in dp.items():
                for v in range(K):
                    add = 0
                    for u in range(K):
                        if seen >> u & 1:
                            add |= 1 << (u * K + v)
                    new_pairs = pairs | add
                    if new_pairs & xbit:
                        continue
                    state = (seen | (1 << v), new_pairs)
                    ndp[state] = (ndp.get(state, 0) + ways) % MOD
            dp = ndp
        return dp.get(((1 << K) - 1, target), 0)

    # When the length-M pattern universe is small, track all observed
    # subsequences at each length while ensuring X remains absent.
    if K ** M <= 27:
        xidx = 0
        for v in X:
            xidx = xidx * K + v - 1
        xbit = 1 << xidx
        target = ((1 << (K ** M)) - 1) ^ xbit

        # Number of suffixes that avoid completing X, by current greedy
        # matched-prefix length q.
        avoid = [[0] * M for _ in range(N + 1)]
        for q in range(M):
            avoid[0][q] = 1
        for r in range(1, N + 1):
            for q in range(M):
                avoid[r][q] = sum(
                    avoid[r - 1][nq]
                    for v in range(K)
                    if (nq := q + (v + 1 == X[q])) < M
                ) % MOD

        empty = tuple([0] * M)
        dp = {(empty, 0): 1}
        answer = 0
        for length in range(N):
            ndp = {}
            remaining = N - length - 1
            for (masks, q), ways in dp.items():
                for v in range(K):
                    nq = q + (v + 1 == X[q])
                    if nq == M:
                        continue
                    new_masks = [0] * M
                    new_masks[0] = masks[0] | (1 << v)
                    for size in range(2, M + 1):
                        prev = masks[size - 2]
                        add = 0
                        while prev:
                            bit = prev & -prev
                            p = bit.bit_length() - 1
                            add |= 1 << (p * K + v)
                            prev -= bit
                        new_masks[size - 1] = masks[size - 1] | add
                    if new_masks[-1] & xbit:
                        continue
                    if new_masks[-1] == target:
                        answer = (answer + ways * avoid[remaining][nq]) % MOD
                    else:
                        state = (tuple(new_masks), nq)
                        ndp[state] = (ndp.get(state, 0) + ways) % MOD
            dp = ndp
        return answer

    # Exact enumeration is practical only for small sequence spaces.
    if K ** N <= 2_000_000:
        wanted = tuple(X)
        answer = 0
        for seq in product(range(1, K + 1), repeat=N):
            seen = set()
            for indices in combinations(range(N), M):
                seen.add(tuple(seq[i] for i in indices))
                if len(seen) == K ** M:
                    break
            if len(seen) == K ** M - 1 and wanted not in seen:
                answer += 1
        return answer % MOD

    return 0

