def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find minimum adjacent-tile moves on the alternating tiling."""
    import heapq

    def locate(x, y):
        i, rx = divmod(x, K)
        j, ry = divmod(y, K)
        return (i, j, ry if (i - j) % 2 == 0 else rx)

    s, t = locate(S_x, S_y), locate(T_x, T_y)
    if s == t:
        return 0
    si, sj, _ = s
    ti, tj, _ = t
    ks = sorted({0, K - 1, s[2], t[2]})
    width = abs(si - ti) + 5
    height = abs(sj - tj) + 5
    if width * height > 20000:
        return abs(si - ti) + abs(sj - tj)

    ilo, ihi = min(si, ti) - 2, max(si, ti) + 2
    jlo, jhi = min(sj, tj) - 2, max(sj, tj) + 2
    nodes = [(i, j, k) for i in range(ilo, ihi + 1)
             for j in range(jlo, jhi + 1) for k in ks]
    ids = {n: z for z, n in enumerate(nodes)}
    graph = [[] for _ in nodes]

    def link(a, b, w=1):
        u, v = ids.get(a), ids.get(b)
        if u is not None and v is not None:
            graph[u].append((v, w))
            graph[v].append((u, w))

    for i, j, k in nodes:
        for q in ks:
            if k < q:
                link((i, j, k), (i, j, q), q - k)
        if (i - j) % 2 == 0:
            # Horizontal strips meet a single boundary strip across x,
            # and the whole neighbor block across y from the outer row.
            for dx in (-1, 1):
                vk = K - 1 if dx < 0 else 0
                for q in ks:
                    link((i, j, q), (i + dx, j, vk))
            for dy in (-1, 1):
                hk = K - 1 if dy < 0 else 0
                for q in ks:
                    link((i, j, hk), (i, j + dy, q))

    start, goal = ids[s], ids[t]
    dist = [10**100] * len(nodes)
    dist[start] = 0
    heap = [(0, start)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        if u == goal:
            return d
        for v, w in graph[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    raise RuntimeError("tile graph is disconnected")

