def count_special_permutations(A: int, B: int, M: int) -> int:
    """Count permutations satisfying the LIS, LDS, and append condition.

    Under RSK, a permutation of length AB-1 with LIS A and LDS B has the
    unique shape (A, ..., A, A-1), with B rows. Appending a value must add
    the missing lower-right box. The insertion tableau must therefore obey
    the corresponding boundary inequalities. This routine counts those
    tableaux as linear extensions of the Young diagram with the extra
    boundary order relations, then excludes tableaux whose two top-right
    entries are consecutive.
    """
    if A < 2 or B < 2:
        return 0

    lengths = [A] * (B - 1) + [A - 1]
    n = A * B - 1
    base = A + 1
    powers = [base ** i for i in range(B)]
    final = sum(lengths[i] * powers[i] for i in range(B))

    def row(code, i):
        return (code // powers[i]) % base

    def successors(code):
        out = []
        for i in range(B):
            cur = row(code, i)
            if cur >= lengths[i]:
                continue
            if i and row(code, i - 1) == cur:
                continue
            new_len = cur + 1
            if new_len == A and i + 1 < B and row(code, i + 1) < A - 1:
                continue
            out.append(code + powers[i])
        return out

    levels = [[0]]
    forward = {0: 1}
    for _ in range(n):
        nxt = set()
        nxt_count = {}
        for code in levels[-1]:
            ways = forward[code]
            for child in successors(code):
                nxt.add(child)
                nxt_count[child] = (nxt_count.get(child, 0) + ways) % M
        levels.append(list(nxt))
        forward.update(nxt_count)

    backward = {final: 1}
    bad = 0
    top_two = 2 * powers[0]
    for layer in reversed(levels[:-1]):
        prev = {}
        for code in layer:
            ways = 0
            for child in successors(code):
                ways += backward[child]
            ways %= M
            prev[code] = ways
            if row(code, 0) == A and row(code, 1) >= A - 1:
                before_pair = code - top_two
                if before_pair in forward:
                    bad = (bad + forward[before_pair] * ways) % M
        backward = prev

    good_tableaux = (forward[final] - bad) % M

    hook_product = 1
    for i, width in enumerate(lengths):
        for j in range(width):
            below = sum(1 for r in range(i, B) if lengths[r] > j)
            hook = width - j + below - 1
            hook_product = hook_product * hook % M
    factorial = 1
    for x in range(2, n + 1):
        factorial = factorial * x % M
    tableaux = factorial * pow(hook_product, M - 2, M) % M
    return tableaux * good_tableaux % M
